parameters.jsCode:
// Consolida dados do HubSpot em JSON estruturado
const contact = $node['HubSpot - Get Contact'].json;
const emailsResponse = $node['HubSpot - Get Emails'].json;
const dealsResponse = $node['HubSpot - Get Deals'].json;
const ticketsResponse = $node['HubSpot - Get Tickets'].json;

const emails = emailsResponse.results || [];
const deals = dealsResponse.results || [];
const tickets = ticketsResponse.results || [];

const consolidatedData = {
  contact: {
    id: contact.id,
    name: `${contact.properties.firstname} ${contact.properties.lastname}`,
    email: contact.properties.email,
    phone: contact.properties.phone,
    company: contact.properties.company || 'N/A',
    created_date: contact.properties.createdate
  },
  summary: {
    total_emails: emails.length,
    total_deals: deals.length,
    total_tickets: tickets.length
  },
  deals: deals.slice(0, 5).map(d => ({
    id: d.id,
    name: d.properties.dealname || 'Sem nome',
    stage: d.properties.dealstage || 'unknown',
    amount: d.properties.amount || '0',
    close_date: d.properties.closedate || null
  })),
  emails: emails.slice(0, 10).map(e => ({
    subject: e.properties?.hs_email_subject || 'Sem assunto',
    direction: e.properties?.hs_email_direction || 'UNKNOWN',
    timestamp: e.properties?.hs_timestamp || null
  })),
  tickets: tickets.slice(0, 5).map(t => ({
    id: t.id,
    subject: t.properties?.subject || 'Sem assunto',
    status: t.properties?.hs_ticket_priority || 'unknown',
    created_date: t.properties?.createdate || null
  }))
};

return {
  json: {
    hubspot_data: consolidatedData,
    customer_phone: contact.properties.phone,
    customer_name: `${contact.properties.firstname} ${contact.properties.lastname}`
  }
};

// Parse resposta do Agente 2 (Context Analyzer)
const tessResponse = $input.first().json;
const output = tessResponse.responses?.[0]?.output || '';

try {
  const analysis = JSON.parse(output);

  if (!analysis.summary || !analysis.sentiment) {
    throw new Error('Análise incompleta');
  }

  return {
    json: {
      analysis: analysis,
      customer_phone: $node['Consolidate HubSpot Data'].json.customer_phone,
      customer_name: $node['Consolidate HubSpot Data'].json.customer_name,
      tess_credits_agent2: tessResponse.responses?.[0]?.credits
    }
  };

} catch (error) {
  console.error('Erro ao parsear Agente 2:', error);

  return {
    json: {
      analysis: {
        summary: 'Análise automática não disponível',
        sentiment: 'neutral',
        suggested_tone: 'curious',
        key_events: [],
        red_flags: [],
        personalization_points: []
      },
      customer_phone: $node['Consolidate HubSpot Data'].json.customer_phone,
      customer_name: $node['Consolidate HubSpot Data'].json.customer_name
    }
  };
}

// Parse resposta do Agente 3 (Message Generator)
const tessResponse = $input.first().json;
const message = tessResponse.responses?.[0]?.output || '';

if (!message || message.length < 10) {
  throw new Error('Mensagem inválida ou vazia');
}

if (message.length > 500) {
  console.warn('Mensagem muito longa:', message.length);
}

return {
  json: {
    message: message.trim(),
    customer_phone: $node['Parse Agent 2 Response'].json.customer_phone,
    customer_name: $node['Parse Agent 2 Response'].json.customer_name,
    analysis: $node['Parse Agent 2 Response'].json.analysis,
    tess_credits_agent3: tessResponse.responses?.[0]?.credits
  }
};

// Parse mensagem da API Meta WhatsApp
const body = $input.first().json.body || $input.first().json;

const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;
const messages = value?.messages?.[0];
const contacts = value?.contacts?.[0];

if (!messages) {
  return { json: { skip: true } };
}

const phoneNumber = messages.from;
const messageText = messages.text?.body || '';
const messageId = messages.id;
const timestamp = messages.timestamp;

return {
  json: {
    phone: '+' + phoneNumber,
    message: messageText,
    message_id: messageId,
    from_me: false,
    timestamp: new Date(parseInt(timestamp) * 1000).toISOString(),
    contact_name: contacts?.profile?.name || 'Cliente'
  }
};

// Prepara input para Agente 4 (Tess)
// Sintaxe moderna do n8n
const survey = $('Supabase - Get Survey').first().json;
const newMessage = $('Parse Meta Message').first().json.message;

// Parse conversation_transcript do banco e FAZER CÓPIA
let history = [];
if (survey.conversation_transcript) {
  if (typeof survey.conversation_transcript === 'string') {
    history = [...JSON.parse(survey.conversation_transcript)];
  } else if (Array.isArray(survey.conversation_transcript)) {
    history = [...survey.conversation_transcript];  // CÓPIA do array!
  }
}

// Adiciona mensagem do cliente ao histórico
history.push({
  role: 'user',
  content: newMessage
});

const turnCount = Math.floor(history.length / 2) + 1;
const contextSummary = survey.context_summary || 'Cliente respondendo pesquisa de satisfação';

const inputForTess = {
  conversation_history: history,
  turn_count: turnCount,
  context_summary: contextSummary
};

return {
  json: {
    survey_id: survey.id,
    phone: $('Parse Meta Message').first().json.phone,
    tess_input: inputForTess,
    conversation_history: history,
    current_score: survey.satisfaction_score,
    current_sentiment: survey.sentiment,
    current_feedback: survey.main_feedback
  }
};

// Parse resposta da Tess
const tessResponse = $input.first().json;
const rawOutput = tessResponse.responses?.[0]?.output || '';
// Remove marcações markdown se presentes (```json ... ```)
const output = rawOutput.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();

try {
  const parsed = JSON.parse(output);

  if (!parsed.response || !parsed.status || !parsed.extracted_data) {
    throw new Error('JSON incompleto');
  }

  if (!parsed.extracted_data.sentiment && parsed.extracted_data.satisfaction_score) {
    const score = parsed.extracted_data.satisfaction_score;
    parsed.extracted_data.sentiment = score >= 4 ? 'positive' : score === 3 ? 'neutral' : 'negative';
  }

  return { 
    json: {
      ...parsed,
      tess_response_id: tessResponse.responses?.[0]?.id,
      tess_credits: tessResponse.responses?.[0]?.credits
    }
  };

} catch (error) {
  console.error('Erro ao parsear resposta Tess:', error);

  if (output && typeof output === 'string') {
    return {
      json: {
        response: output,
        status: 'continue',
        extracted_data: {
          satisfaction_score: null,
          main_feedback: null,
          sentiment: null
        },
        tess_response_id: tessResponse.responses?.[0]?.id
      }
    };
  }

  return {
    json: {
      response: 'Obrigada pelo contato!',
      status: 'escalate',
      extracted_data: {
        satisfaction_score: null,
        main_feedback: 'Erro ao processar resposta',
        sentiment: 'neutral'
      }
    }
  };
}

// Preparar dados para update no Supabase
// Sintaxe moderna do n8n
const survey = $('Supabase - Get Survey').first().json;
const tessResponse = $('Parse Tess Response').first().json;
const prepareData = $('Prepare Tess Input').first().json;

// Fazer CÓPIA do histórico antes de modificar
const conversationHistory = [...prepareData.conversation_history];

// Adicionar resposta do bot ao histórico
conversationHistory.push({
  role: 'assistant',
  content: tessResponse.response
});

// Preservar dados já extraídos (não sobrescrever com null)
const finalScore = tessResponse.extracted_data.satisfaction_score || prepareData.current_score || null;
const finalSentiment = tessResponse.extracted_data.sentiment || prepareData.current_sentiment || null;
const finalFeedback = tessResponse.extracted_data.main_feedback || prepareData.current_feedback || null;

return {
  json: {
    survey_id: survey.id,
    conversation_transcript: JSON.stringify(conversationHistory),
    satisfaction_score: finalScore,
    main_feedback: finalFeedback,
    sentiment: finalSentiment,
    status: tessResponse.status === 'completed' ? 'completed' : 'active'
  }
};

